"content": "{
  "claims": [
    {
      "claim": "African green H2 delivered to Europe costs €3.64-6.13/kgH2 across all scenarios",
      "evidence": "outputs/full_results.csv, outputs/scenario_summary.csv",
      "verified": true,
      "method": "Direct computation from LCOH model"
    },
    {
      "claim": "All 30 sites competitive against European production in all scenarios",
      "evidence": "outputs/key_results.json - all scenarios show 100% competitive",
      "verified": true,
      "method": "Comparison of delivered cost vs EU benchmark"
    },
    {
      "claim": "Best site is hex_022 (lat -17.35, lon 22.02) with €4.97/kgH2 baseline delivered cost",
      "evidence": "outputs/key_results.json, outputs/full_results.csv",
      "verified": true,
      "method": "Sorting all sites by total_delivered cost"
    },
    {
      "claim": "De-risking from WACC 10% to 6% reduces mean delivered cost by 18.5%",
      "evidence": "Baseline mean €5.18, Full de-risking mean €4.22, reduction = (5.18-4.22)/5.18 = 18.5%",
      "verified": true,
      "method": "Direct calculation from scenario_summary.csv"
    },
    {
      "claim": "Rising interest rates increase costs by 11% but widen competitive advantage",
      "evidence": "Baseline mean €5.18, Rising IR mean €5.75 (+11.0%), EU benchmark rises from €8.33 to €9.49",
      "verified": true,
      "method": "Direct calculation from scenario_summary.csv"
    },
    {
      "claim": "NH3 pathway adds €1.5-2.3/kgH2 (30-40% of total)",
      "evidence": "NH3 synthesis ~€1.04 + shipping ~€0.50 + cracking ~€0.80 = ~€2.34 for baseline best site",
      "verified": true,
      "method": "Sum of nh3_conversion + shipping + reconversion from full_results.csv"
    },
    {
      "claim": "Production costs align with literature (€1.54-3.22/kgH2)",
      "evidence": "Müller et al. 2030 projection: €1.8-3.0; Halloran et al.: €5.43-9.21 (current); IEA: $2.50",
      "verified": true,
      "method": "Comparison with published values from related_work papers"
    }
  ]
}
